export function buildLeasingTenantsSchedule(startISO = null) {
  return buildScheduleFor(LEASING_TENANTS_MODULES, startISO, LEASING_TENANTS_META.cadenceDays);
}

export function leasingTenantsProgressSummary(progress = {}) {
  return progressSummaryFor(LEASING_TENANTS_MODULES, progress);
}

export function exportLeasingTenantsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: LEASING_TENANTS_META,
    modules: buildLeasingTenantsSchedule(startISO),
    sessionFlow: LEASING_TENANTS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function leasingTenantsRefs() {
  const seen = new Set();
  for (const m of LEASING_TENANTS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((LEASING_TENANTS_META.wordFirst && LEASING_TENANTS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

